  'guide.controls.deeds': 'Bedrifternas bok',
  'guide.deedsPage.cat.chronicle': 'Krönikor',
  'guide.deedsPage.cat.collection': 'Samling',
  'guide.deedsPage.cat.combat': 'Strid',
  'guide.deedsPage.cat.delve': 'Delver',
